import { isFavorite, type Favorite } from '../package/favorites'

/** Demo data bundled with the app (generated by scripts/sync-engine.mjs). */
export interface DemoData {
  /** Preparation package envelope (JSON text). */
  package: string
  /** A finished FEB game (JSON text) replayed as if it were live. */
  game: string
}

/** A recorded match the app can replay (public/demo/index.json, generated by scripts/sync-engine.mjs). */
export interface DemoMatch {
  code: string
  title: string
  /** Local date-time of the kick-off, ISO without zone. */
  date: string
  home: { id: string; name: string }
  away: { id: string; name: string }
  recording: string
  package: string
  /** `SEGUNDA FEB · Liga Regular A`; absent in a manifest from before it existed (issue #441). */
  competition?: string
  /** The team whose point of view the package has. */
  teamId?: string
}

/** The preparation package and the packed recording of a match. */
export interface RealDemoData {
  package: string
  recording: string
}

/** Recorded matches, newest first (the first is the default). Anything unreadable is "no recordings". */
export async function loadManifest(): Promise<DemoMatch[]> {
  try {
    const response = await fetch(`${location.origin}/demo/index.json`)
    if (!response.ok) return []
    const body: unknown = await response.json()
    return Array.isArray(body) ? (body as DemoMatch[]) : []
  } catch {
    return []
  }
}

export async function loadMatch(match: DemoMatch): Promise<RealDemoData> {
  const get = async (file: string) => {
    const response = await fetch(`${location.origin}/demo/${file}`)
    if (!response.ok) throw new Error(`Falta ${file} del partido ${match.code} (HTTP ${response.status})`)
    return response.text()
  }
  const [pkg, recording] = await Promise.all([get(match.package), get(match.recording)])
  return { package: pkg, recording }
}

export async function loadDemoData(): Promise<DemoData> {
  const [pkg, game] = await Promise.all([
    fetch(`${location.origin}/demo/package.json`).then(r => r.text()),
    fetch(`${location.origin}/demo/game.json`).then(r => r.text()),
  ])
  return { package: pkg, game }
}

/** The demos of the teams "de interés" first (recognised in either side, by id or by name); the rest keep their order. Nothing is modified. */
export function orderDemos(matches: DemoMatch[], favorites: Favorite[]): DemoMatch[] {
  if (favorites.length === 0) return matches
  const interesting = (m: DemoMatch) => [m.home, m.away, ...(m.teamId ? [{ id: m.teamId, name: '' }] : [])]
    .some(side => favorites.some(f => f.teamId === side.id || (side.name !== '' && isFavorite([f], side.id, side.name))))
  return [...matches.filter(interesting), ...matches.filter(m => !interesting(m))]
}

/** What the selector shows: the competition (when the manifest has it) and the match. */
export function demoLabel(match: DemoMatch): string {
  return match.competition ? `${match.competition} — ${match.title}` : match.title
}
